mapper.select:
SELECT review_id, title, content, writer, "date", product_id, file_name, file_type, file_data
FROM review
WHERE review_id = #{reviewId}

mapper.update:
UPDATE review SET title = #{title}, content = #{content}, writer = #{writer}, product_id = #{productId}
, file_name = NULL, file_type = NULL, file_data = NULL
, file_name = #{fileName}, file_type = #{fileType}, file_data = #{fileData,jdbcType=BLOB,typeHandler=org.apache.ibatis.type.BlobTypeHandler}
WHERE review_id = #{reviewId}
